//! `/api/v1/agents`: the token user's own agents (guides/api.md). Generated by `cargo offrails generate api agents`.
//! Every lookup goes through `agent::find_for`, so another user's id is 404; writes need the
//! `write` scope (403).

use axum::{
    Json,
    extract::{Path, State},
    http::StatusCode,
    response::{IntoResponse, Response},
};

use crate::{
    controllers::api::{ApiJson, ApiUser, ErrorBody, InvalidBody, PageInfo},
    error::AppError,
    models::{Page, agent, agent::AgentParams},
    state::AppState,
    views::agents_json::{AgentBody, AgentInput, AgentJson, AgentsPage},
};

#[utoipa::path(
    get,
    path = "/api/v1/agents",
    tag = "agents",
    security(("bearer" = [])),
    params(
        ("page" = Option<u64>, Query, description = "1-based"),
        ("per" = Option<u64>, Query, description = "1 to 100, default 25")
    ),
    responses((status = 200, body = AgentsPage), (status = 401, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn index(
    State(s): State<AppState>,
    me: ApiUser,
    page: Page,
) -> Result<Json<AgentsPage>, AppError> {
    let (rows, more) = agent::all_for(&s.db, &me.user, page).await?;
    Ok(Json(AgentsPage {
        data: rows.iter().map(AgentJson::from).collect(),
        page: PageInfo {
            page: page.number(),
            per: page.per(),
            has_more: more,
        },
    }))
}

#[utoipa::path(
    get,
    path = "/api/v1/agents/{id}",
    tag = "agents",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    responses((status = 200, body = AgentBody), (status = 401, body = ErrorBody), (status = 404, body = ErrorBody))
)]
#[tracing::instrument(skip_all)]
pub async fn show(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
) -> Result<Json<AgentBody>, AppError> {
    let record = agent::find_for(&s.db, &me.user, id).await?;
    Ok(Json(AgentBody {
        data: AgentJson::from(&record),
    }))
}

#[utoipa::path(
    post,
    path = "/api/v1/agents",
    tag = "agents",
    security(("bearer" = [])),
    request_body = AgentInput,
    responses((status = 201, body = AgentBody), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn create(
    State(s): State<AppState>,
    me: ApiUser,
    ApiJson(input): ApiJson<AgentInput>,
) -> Result<Response, AppError> {
    me.require_write()?;
    let new = input
        .onto(AgentParams::default())
        .validate()
        .map_err(AppError::Invalid)?;
    let record = agent::create(&s.db, &me.user, new).await?;
    Ok((
        StatusCode::CREATED,
        Json(AgentBody {
            data: AgentJson::from(&record),
        }),
    )
        .into_response())
}

#[utoipa::path(
    patch,
    path = "/api/v1/agents/{id}",
    tag = "agents",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    request_body = AgentInput,
    responses((status = 200, body = AgentBody), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 404, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn update(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
    ApiJson(input): ApiJson<AgentInput>,
) -> Result<Json<AgentBody>, AppError> {
    me.require_write()?;
    let record = agent::find_for(&s.db, &me.user, id).await?;
    let new = input
        .onto(AgentParams::from(&record))
        .validate()
        .map_err(AppError::Invalid)?;
    let record = agent::update_for(&s.db, &me.user, record, new).await?;
    Ok(Json(AgentBody {
        data: AgentJson::from(&record),
    }))
}

#[utoipa::path(
    delete,
    path = "/api/v1/agents/{id}",
    tag = "agents",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    responses((status = 204), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 404, body = ErrorBody))
)]
#[tracing::instrument(skip_all)]
pub async fn destroy(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
) -> Result<StatusCode, AppError> {
    me.require_write()?;
    let record = agent::find_for(&s.db, &me.user, id).await?;
    agent::destroy_for(&s.db, &me.user, record).await?;
    Ok(StatusCode::NO_CONTENT)
}
